mapper.update:
UPDATE paper
SET question_ids = #{row.questionIds}, question_count = #{row.questionCount},
    batch_id = #{row.batchId}, source_sha256 = #{row.sourceSha256},
    source_url = #{row.sourceUrl}, warning_count = #{row.warningCount},
    warnings_json = #{row.warningsJson}
WHERE id = #{id}

UPDATE question
SET stem_html = #{stemHtml}, analysis_html = #{analysisHtml}, stem_text = #{stemText},
    correct = #{correct}, answer_text = #{answerText}, status = #{status},
    status_reason = #{statusReason}, display_ready = #{displayReady},
    license_tag = #{licenseTag}, batch_id = #{batchId}, assets_json = #{assetsJson}
WHERE id = #{id}
